import json
from pathlib import Path
config = json.loads(Path("config.json").read_text())
rows = [{"id": 1, "name": "Ada"}]
if config["format"] == "json":
    print(json.dumps(rows))
elif config["format"] == "csv":
    print("id,name\n1,Ada")
else:
    raise ValueError("Unsupported export format")
